import base64,os,subprocess,ast
code=base64.b64decode("").decode("utf-8")
ast.parse(code)
open("/content/fly/char_loop4.py","w",encoding="utf-8").write(code)
ps=subprocess.run("ps -eo pid,cmd | grep [c]har_loop4.py",shell=True,capture_output=True,text=True).stdout.strip()
if not ps:
    subprocess.Popen("nohup python -u /content/fly/char_loop4.py > /content/fly/char4.log 2>&1 &",shell=True,executable="/bin/bash")
    print("LAUNCHED")
else: print("running", ps)
